/** @sly2-annot addr=0x15E3E8
 * Purpose: Tests one candidate LO against the search flags/context and records it in the result array
 *   (best-distance logic)
 * Info: proposed name MatchSwObject (T1); TU find
 * Confidence: mid (draft) [T1 0.70] - evidence: static analysis; sources: r3_1539A8
 * See: docs/reference/functions/object-model.md#find-0x15e380-0x15ef00
 * @end-sly2-annot */
extern "C" void MatchSwObject(void *pv, LO *plo, CH *pch, unsigned int grf, LO *ploCtx, CH *pchList, int cMax, int *pc,
                              LO **aplo, int *pips)
{
    LO *p;
    if ((grf & 0x400) == 0) {
        CH *q;
        switch (plo->k) {
        case 0:
            q = pchList;
            while (1) {
                if (!q)
                    return;
                if (IsrcFromIdProxy((int)q->p) == IsrcFromIdProxy((int)pch->p))
                    break;
                if (grf & 0x800)
                    return;
                q = q->pNext;
            }
            break;
        case -1:
            while (pchList != pch) {
                if (!pchList || (grf & 0x800))
                    return;
                pchList = pchList->pNext;
            }
            break;
        case 1:
            break;
        }
    }
    switch (grf & 0xFF) {
    case 2:
        if (plo->pParent == ploCtx)
            goto LAdd;
        return;
    case 1:
        for (p = plo; p; p = p->pParent) {
            if (p->ips == 0)
                continue;
            if (p->ips == 1)
                goto LAdd;
            return;
        }
        return;
    case 3:
        if (plo->ips >= 2)
            goto LAdd;
        return;
    case 4: {
        for (p = plo; p; p = p->pParent) {
            int i = p->ips;
            if (i != 0 && i < *pips) {
                if ((grf & 0x100) && (int)plo->f == 0)
                    return;
                *pips = i;
                *pc = 0;
                goto LAdd2;
            }
        }
        if (*pips != 0x7FFFFFFF || p)
            return;
        goto LAdd;
    }
    case 5:
    LAdd:
        if ((grf & 0x100) && (int)plo->f == 0)
            return;
    LAdd2:
        if (*pc < cMax)
            aplo[*pc] = plo;
        (*pc)++;
        break;
    }
}

